// ReplaceDjangoInstanceCmd represents the command 'tptctl django replace django-instance'
var ReplaceDjangoInstanceCmd = &cobra.Command{
	Example: "  # replace using a config file\n  tptctl django replace django-instance --config path/to/config.yaml --name some-django-instance",
	Long:    "Replace an existing django instance.\n Note that the entire object will replaced with a PUT request.\n All fields must be provided in the config file.",
	PreRun:  CommandPreRunFunc,
	Run: func(cmd *cobra.Command, args []string) {
		apiClient, _, apiEndpoint, _ := tptctl_cmd.GetClientContext(cmd)

		// replace django instance based on version
		switch djangoVersion {
		case "v0":
			var djangoInstanceConfig config_v0.DjangoInstanceConfig
			// load django instance config
			configContent, err := cli.ReadConfigContent(djangoConfigPath, djangoStdin)
			if err != nil {
				cli.Error("failed to read config", err)
				os.Exit(1)
			}
			if err := yaml.UnmarshalStrict(configContent, &djangoInstanceConfig); err != nil {
				cli.Error("failed to unmarshal config file yaml content", err)
				os.Exit(1)
			}

			// replace django instance
			updatedDjangoInstance, err := djangoInstanceConfig.Replace(apiClient, apiEndpoint, djangoName)
			if err != nil {
				cli.Error("failed to update django instance", err)
				os.Exit(1)
			}

			cli.Complete(fmt.Sprintf("django instance %s updated", *updatedDjangoInstance.DjangoInstance.Name))
		default:
			cli.Error("", errors.New("unrecognized object version"))
			os.Exit(1)
		}
	},
	Short:        "Replace an existing django instance",
	SilenceUsage: true,
	Use:          "django-instance",
}

