// DeleteDjangoInstanceCmd represents the command 'tptctl django delete django-instance'
var DeleteDjangoInstanceCmd = &cobra.Command{
	Example: "  # delete using a config file\n  tptctl django delete django-instance --config path/to/config.yaml\n\n  # delete using name\n  tptctl django delete django-instance --name some-django-instance",
	Long:    "Delete an existing django instance.",
	PreRun:  CommandPreRunFunc,
	Run: func(cmd *cobra.Command, args []string) {
		apiClient, _, apiEndpoint, _ := tptctl_cmd.GetClientContext(cmd)

		// flag validation
		if err := cli.ValidateConfigNameFlags(
			djangoConfigPath,
			djangoName,
			"django instance",
		); err != nil {
			cli.Error("flag validation failed", err)
			os.Exit(1)
		}

		// delete django instance based on version
		switch djangoVersion {
		case "v0":
			var djangoInstanceConfig config_v0.DjangoInstanceConfig
			if djangoConfigPath != "" || djangoStdin {
				// load django instance config
				configContent, err := cli.ReadConfigContent(djangoConfigPath, djangoStdin)
				if err != nil {
					cli.Error("failed to read config", err)
					os.Exit(1)
				}
				if err := yaml.UnmarshalStrict(configContent, &djangoInstanceConfig); err != nil {
					cli.Error("failed to unmarshal config file yaml content", err)
					os.Exit(1)
				}
			} else {
				djangoInstanceConfig = config_v0.DjangoInstanceConfig{
					DjangoInstance: config_v0.DjangoInstanceValues{
						Name: &djangoName,
					},
				}
			}

			// delete django instance
			deletedDjangoInstance, err := djangoInstanceConfig.Delete(apiClient, apiEndpoint)
			if err != nil {
				cli.Error("failed to delete django instance", err)
				os.Exit(1)
			}

			cli.Complete(fmt.Sprintf("django instance %s deleted", *deletedDjangoInstance.DjangoInstance.Name))
		default:
			cli.Error("", errors.New("unrecognized object version"))
			os.Exit(1)
		}
	},
	Short:        "Delete an existing django instance",
	SilenceUsage: true,
	Use:          "django-instance",
}

func init() {
	DeleteCmd.AddCommand(DeleteDjangoInstanceCmd)

	DeleteDjangoInstanceCmd.Flags().StringVarP(
		&djangoConfigPath,
		"config", "c", "", "Path to file with django instance config.",
	)
	DeleteDjangoInstanceCmd.Flags().StringVarP(
		&djangoName,
		"name", "n", "", "Name of django instance.",
	)
	DeleteDjangoInstanceCmd.Flags().StringVarP(
		&cliArgs.ControlPlaneName,
		"control-plane-name", "i", "", "Optional. Name of control plane. Will default to current control plane if not provided.",
	)
	DeleteDjangoInstanceCmd.Flags().StringVarP(
		&djangoVersion,
		"version", "v", "v0", "Version of django instances object to delete. One of: [v0]",
	)
}
